import type { courses } from './courses';
import { appliedLessons } from '../data/applied-foundations';
import { computerLessons } from '../data/computer-foundations';

export type CourseId = (typeof courses)[number]['id'];
type Text = readonly [string, string, string];
export type WorkshopStage = {
  id: string;
  module: string;
  title: Text;
  task: Text;
  verify: Text;
  review: Text;
};
export type CourseWorkshop = {
  contentLanguage?: 'en';
  title: Text;
  brief: Text;
  deliverable: Text;
  stages: readonly WorkshopStage[];
  defense: Text;
};
// Editorial content, bundled offline. Review notes are guidance, not automatic grading.
const stage = (id: string, module: string, title: Text, task: Text, verify: Text, review: Text): WorkshopStage =>
  ({ id, module, title, task, verify, review });
const english = (value: string): Text => [value, value, value];
const englishStage = (id: string, module: string, title: string, task: string, verify: string, review: string) => stage(id, module, english(title), english(task), english(verify), english(review));

// Reuse the actual authored capstone, rather than inventing an unrelated project.
function authoredWorkshop(id: string): CourseWorkshop {
  const lesson = [...appliedLessons, ...computerLessons].find(l => l.id === id)!;
  const text = (value: string): Text => [value, value, value];
  return {
    contentLanguage: 'en',
    title: text(lesson.title), brief: text(lesson.concept), deliverable: text(lesson.exercise.task),
    stages: lesson.curriculum!.rubric.map((r, i) => stage('evidence-' + i, lesson.moduleId, text(r.criterion), text(r.evidence), text('Record the artifact location, expected result, observed result and any limitation. Self-review is not independent certification.'), text(r.revise))),
    defense: text(lesson.whatIf),
  };
}

